/// gRPC bridge gateway for log messages
pub struct LogBridgeGateway {
    config: Config,
}

// -----------------------------------------------------------------------------

impl LogBridgeGateway {
    /// Create new gRPC bridge gateway
    pub fn new(config: &Config) -> Self {
        Self {
            config: config.clone(),
        }
    }

    /// Get server name
    pub fn name(&self) -> &str {
        &self.config.name
    }

    //-----------------------------------------------------------------------------------------------

    /// Run the gRPC server
    pub async fn run(
        &self,
        writer_tx: mpsc::Sender<LogPacket>,
        ring_buffer: Arc<LogRingBuffer>,
    ) -> Result<(), Box<dyn std::error::Error>> {
        let raw_addr = format_bind_target(&self.config.grpc_host, self.config.grpc_port);
        let addr = resolve_grpc_bind_addr(&raw_addr).await?;
        let service = LogBridgeServiceImpl::new(&self.config, writer_tx, ring_buffer);

        print_internal_log(
            "INFO",
            &self.config.name,
            "grpc_server.rs",
            "run",
            line_str!(),
            &format!("Log Bridge listening on {}", addr),
        );

        Server::builder()
            .add_service(LogBridgeServer::new(service))
            .serve(addr)
            .await?;

        Ok(())
    }
}

//-----------------------------------------------------------------------------------------------

/// Resolve a gRPC bind target (`ip:port` literal or `hostname:port`) into a `SocketAddr`.
///
/// Fast-paths literal socket addresses via `str::parse::<SocketAddr>()` and falls back to
/// asynchronous DNS resolution via `tokio::net::lookup_host`, failing fast when empty or unresolved.
pub async fn resolve_grpc_bind_addr(addr: &str) -> Result<SocketAddr, String> {
    let trimmed = addr.trim();
    if trimmed.is_empty() {
        return Err("gRPC bind address cannot be empty".to_string());
    }

    if let Ok(socket_addr) = trimmed.parse::<SocketAddr>() {
        return Ok(socket_addr);
    }

    let mut resolved = tokio::net::lookup_host(trimmed)
        .await
        .map_err(|e| format!("failed to resolve gRPC bind address '{trimmed}': {e}"))?;

    resolved
        .next()
        .ok_or_else(|| format!("gRPC bind address '{trimmed}' resolved to no socket addresses"))
}

//-----------------------------------------------------------------------------------------------

/// Format a configured host and port into a `host:port` (or `[ipv6]:port`) bind target.
fn format_bind_target(host: &str, port: u16) -> String {
    let trimmed = host.trim();
    if trimmed.is_empty() {
        return String::new();
    }
    if trimmed.contains(':') && !trimmed.starts_with('[') {
        format!("[{trimmed}]:{port}")
    } else {
        format!("{trimmed}:{port}")
    }
}

